<?php $markers = array_map(static fn (array $local) => ['lat' => (float) $local['latitude'], 'lng' => (float) $local['longitude'], 'nome' => $local['nome']], $mapLocais); ?>
<section class="perfil-hero"><div class="container"><a class="text-decoration-none" href="<?= base_url('aulas-e-locais') ?>">← Todas as aulas e locais</a><div class="perfil-grid mt-4"><?php if ($instrutor['foto_perfil']) : ?><img class="perfil-photo" src="<?= base_url('uploads/' . $instrutor['foto_perfil']) ?>" alt="<?= esc($instrutor['apelido'], 'attr') ?>"><?php else : ?><div class="perfil-photo perfil-placeholder" aria-hidden="true"><?= esc(mb_strtoupper(mb_substr($instrutor['apelido'], 0, 1))) ?></div><?php endif ?><div><span class="perfil-rank"><?= esc($instrutor['graduacao']) ?></span><h1><?= esc($instrutor['apelido']) ?></h1><p class="lead mb-0"><?= esc($instrutor['nome']) ?></p></div></div></div></section>
<section class="container perfil-content"><div class="row g-5"><div class="col-lg-7"><h2>Sobre</h2><p class="perfil-bio"><?= esc($instrutor['biografia'] ?: 'Biografia em atualização.') ?></p><?php if ($instrutor['fotos']) : ?><h2 class="mt-5">Galeria</h2><div class="perfil-gallery"><?php foreach ($instrutor['fotos'] as $foto) : ?><img src="<?= base_url('uploads/' . $foto) ?>" alt="Foto de <?= esc($instrutor['apelido'], 'attr') ?>"><?php endforeach ?></div><?php endif ?></div><div class="col-lg-5"><h2>Onde ministra</h2><div class="row g-3"><?php foreach ($locais as $local) : ?><div class="col-12"><article class="perfil-local"><h3 class="h5"><?= esc($local['nome']) ?></h3><?php if ($local['endereco']) : ?><p class="mb-1"><?= esc($local['endereco']) ?></p><?php endif ?><?php if ($local['dias_horarios']) : ?><small class="text-muted"><?= esc($local['dias_horarios']) ?></small><?php endif ?></article></div><?php endforeach ?><?php if ($locais === []) : ?><p class="text-muted">Nenhum local informado.</p><?php endif ?></div></div></div><?php if ($markers) : ?><div id="perfil-map" class="perfil-map" aria-label="Mapa dos locais de aula"></div><?php endif ?></section>
<?= $this->endSection() ?>
<?= $this->section('scripts') ?><?php if ($markers) : ?><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>const markers=<?= json_encode($markers, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?>,escapeHtml=value=>String(value).replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[char])),map=L.map('perfil-map',{scrollWheelZoom:false}),bounds=[];L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(map);markers.forEach(item=>{L.marker([item.lat,item.lng]).addTo(map).bindPopup(escapeHtml(item.nome));bounds.push([item.lat,item.lng])});map.fitBounds(bounds,{padding:[35,35],maxZoom:14});</script><?php endif ?><?= $this->endSection() ?>
